    s.scene.root->removeChild(selector);s.scene.baseModel=0;if(s.flat)s.flat->model=SoTexture2::MODULATE;if(s.volume)s.volume->model=SoTexture3::MODULATE;if(s.cube)s.cube->model=SoTextureCubeMap::MODULATE;
