std::vector<uint8_t> sobel(const std::vector<uint8_t>&height,unsigned w,unsigned h){std::vector<uint8_t>out;auto at=[&](int x,int y){return int(height[size_t((y%int(h)+h)%h)*w+(x%int(w)+w)%w]);};for(int y=0;y<int(h);++y)for(int x=0;x<int(w);++x){int dx=0,dy=0;const int weights[]={1,2,1};for(int k=-1;k<=1;++k){dx+=weights[k+1]*(at(x+1,y+k)-at(x-1,y+k));dy+=weights[k+1]*(at(x+k,y-1)-at(x+k,y+1));}const float a=-float(dx)/255.f,b=-float(dy)/255.f,length=std::sqrt(a*a+b*b+1.f);for(float v:{a/length,b/length,1.f/length})out.push_back(uint8_t(std::min(255.f,(v+1.f)*128.f)));}return out;}

